from itertools import product
from dataclasses import dataclass
from typing import Tuple

@dataclass(frozen=True)
class Barrier:
    techniques: Tuple[str, ...]
    strength: Tuple[int, ...]
    ceiling: int
    def blocks(self, target: int) -> bool:
        return self.ceiling < target

def join(b1: Barrier, b2: Barrier) -> Barrier:
    ts, ss = [], []
    for (t1, s1), (t2, s2) in product(zip(b1.techniques, b1.strength), zip(b2.techniques, b2.strength)):
        ts.append(f'({t1},{t2})'); ss.append(max(s1, s2))
    return Barrier(tuple(ts), tuple(ss), max(b1.ceiling, b2.ceiling))

def meet(b1: Barrier, b2: Barrier) -> Barrier:
    ts, ss = [], []
    for (t1, s1), (t2, s2) in product(zip(b1.techniques, b1.strength), zip(b2.techniques, b2.strength)):
        ts.append(f'({t1},{t2})'); ss.append(min(s1, s2))
    return Barrier(tuple(ts), tuple(ss), min(b1.ceiling, b2.ceiling))

R = Barrier(('oracleA', 'oracleB'), (3, 5), 5)
N = Barrier(('largeness', 'constructivity'), (4, 7), 7)
j, m = join(R, N), meet(R, N)
for t in range(3, 10):
    rb, nb = R.blocks(t), N.blocks(t)
    assert j.blocks(t) == (rb and nb)
    assert m.blocks(t) == (rb or nb)
    print(t, j.blocks(t), m.blocks(t))
print('join = AND, meet = OR verified')

import random
from dataclasses import dataclass
from itertools import product
from typing import Tuple

@dataclass(frozen=True)
class Barrier:
    strength: Tuple[int, ...]
    ceiling: int

def jc(a, b):
    return max(a.ceiling, b.ceiling)

def mc(a, b):
    return min(a.ceiling, b.ceiling)

def rand_b(rng):
    c = rng.randint(0, 20)
    k = rng.randint(1, 4)
    return Barrier(tuple(rng.randint(0, c) for _ in range(k)), c)

rng = random.Random(20260612)
for _ in range(5000):
    a, b, c = (rand_b(rng) for _ in range(3))
    assert jc(a, b) == jc(b, a) and mc(a, b) == mc(b, a)
    assert max(jc(a, b), c.ceiling) == max(a.ceiling, jc(b, c))
    assert min(mc(a, b), c.ceiling) == min(a.ceiling, mc(b, c))
    assert max(a.ceiling, a.ceiling) == a.ceiling
    assert max(a.ceiling, min(a.ceiling, b.ceiling)) == a.ceiling
    assert min(a.ceiling, max(a.ceiling, b.ceiling)) == a.ceiling
    assert max(a.ceiling, min(b.ceiling, c.ceiling)) == min(max(a.ceiling, b.ceiling), max(a.ceiling, c.ceiling))
print('All distributive-lattice laws verified on 5000 random triples')

import random
from typing import List, Tuple, Optional

def card_bool_fn(n: int) -> int:
    return 2 ** (2 ** n)

def enumerate_bool_fns(n: int) -> List[Tuple[bool, ...]]:
    rows = 2 ** n
    return [tuple(bool((k >> i) & 1) for i in range(rows)) for k in range(2 ** rows)]

def shannon_incomplete(n: int, inventory: List[Tuple[bool, ...]]) -> Optional[Tuple[bool, ...]]:
    if len(inventory) >= card_bool_fn(n):
        return None
    seen = set(inventory)
    for f in enumerate_bool_fns(n):
        if f not in seen:
            return f
    return None

for n in range(0, 6):
    print(f'|BoolFn {n}| = 2^(2^{n}) = {card_bool_fn(n)}')
n = 2
all_fns = enumerate_bool_fns(n)
assert len(all_fns) == card_bool_fn(n)
rng = random.Random(7)
inv = rng.sample(all_fns, 10)
hard = shannon_incomplete(n, inv)
assert hard is not None and hard not in inv
print('Guaranteed hard function omitted by inventory:', hard)

